def decide(recipient_reputation, round_num, my_history):
    # Base threshold: decreases linearly from 0.3 to -0.3 over first 20 rounds
    threshold = max(0.3 - round_num * 0.03, -0.3)

    # Adjust threshold based on own recent actions
    recent_cooperations = 0
    recent_defections = 0
    for a in reversed(my_history[-5:]):
        if a == 'cooperate':
            recent_cooperations += 1
            recent_defections = 0
        else:
            recent_defections += 1
            recent_cooperations = 0
        if recent_cooperations >= 3 or recent_defections >= 3:
            break

    # After a long cooperative streak, become more cautious (raise threshold)
    if recent_cooperations >= 3:
        threshold += 0.2
    # After a long defection streak, become more forgiving (lower threshold)
    if recent_defections >= 3:
        threshold -= 0.3

    return recipient_reputation > threshold

